import os
import google.generativeai as genai

def analyze_safety(text: str) -> dict:
    genai.configure(api_key=os.environ["GEMINI_API_KEY"])
    model = genai.GenerativeModel('gemini-1.5-flash-latest')

    # The Google Generative AI API's safety settings are applied during content generation.
    # To 'analyze' existing text for safety, we can attempt to generate a response based on it
    # and observe if safety issues are flagged in the response or if the prompt itself
    # would trigger safety blocks. A more direct content moderation API might be preferable
    # for pure analysis, but within the Generative AI API, this is a common approach.
    # Alternatively, one could use a dedicated Content Safety API (e.g., Azure Content Safety).
    # For this example, we'll demonstrate how the Generative AI API handles safety internally
    # when processing a prompt.

    try:
        response = model.generate_content(text, safety_settings=[
            {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
        ])

        # If the API response contains prompt_feedback, it means the *input text*
        # was flagged for safety issues despite our BLOCK_NONE settings for output.
        # This is how the Generative AI API signals unsafe input.
        if response.prompt_feedback and response.prompt_feedback.safety_ratings:
            safety_feedback = []
            for rating in response.prompt_feedback.safety_ratings:
                if rating.blocked:
                    safety_feedback.append({
                        "category": rating.category.name,
                        "probability": rating.probability.name,
                        "blocked": True
                    })
            if safety_feedback:
                return {"flagged_as_unsafe": True, "details": safety_feedback, "redacted_text": text}

        # If no prompt_feedback indicates blocking, we return the original text
        # as not explicitly flagged by the *input* safety filters.
        return {"flagged_as_unsafe": False, "details": [], "redacted_text": text}

    except Exception as e:
        # Catch cases where the prompt itself is blocked before a response can be generated.
        # The specific error message might indicate a safety block.
        if "blocked due to safety reasons" in str(e).lower():
            return {"flagged_as_unsafe": True, "details": [{"category": "UNKNOWN", "probability": "HIGH", "blocked": True}], "redacted_text": text}
        return {"flagged_as_unsafe": True, "details": [{"category": "ERROR", "message": str(e)}], "redacted_text": text}
